head.script:
scwin.trigger1_onclick = function(e) {
    //alert ("바인딩");
    log = "바인딩";
    dataList2.setJSON([{
        "col1": "12321",
        "col2": "11",
        "rowStatus": "R"
    }, {
        "col1": "1232",
        "col2": "22",
        "rowStatus": "R"
    }, {
        "col1": "521323",
        "col2": "22322",
        "rowStatus": "R"
    }, {
        "col1": "e23232e",
        "col2": "33",
        "rowStatus": "R"
