scwin.checkVal = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'div_search_cob_cmts_num_itemTable_0')).getPropertyValue('background-color') == 'rgb(237, 243, 251)';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에 SelectBox 에서 3번째 데이터인 "ee" 를 선택한다.
    //1. Select the third data "ee" in the SelectBox in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('div_search_cob_cmts_num_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('div_search_cob_cmts_num_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 'ee' 가 선택된다.
    //1. 'ee' is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('div_search_cob_cmts_num_label').textContent == 'ee'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 바인딩 버튼을 클릭한다.
    //2. Click the Bind button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 바인딩 팝업이 생성되면서 데이터리스트가 바인딩된다.
    //2. 바인딩 팝업이 생성되면서 데이터리스트가 바인딩된다.
    WebSquare.wUnit.addCommand("assert", "log", "바인딩");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. SelectBox 에 ▼ 버튼을 클릭한다.
    //3. SelectBox 에 ▼ 버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('div_search_cob_cmts_num_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 리스트가 펼쳐진다. 이때, 포커스 (회색) 는 제일 상단인 -전체- 로 된다. (전버전에서는 3번째 데이터인 '521323' 으로 되어 있었음.)
    //3. The list is expanded. At this time, the focus (gray) becomes the top-in-the-whole. (In the previous version, the third data was '521323'.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 02-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
